function renderAdminStats(data){const stats=[["ВСЕГО ИГРОКОВ",data.playersTotal,"Зарегистрированные аккаунты"],["СЕЙЧАС ОНЛАЙН",data.onlineNow,"Активные соединения"],["ЗА 24 ЧАСА",data.last24h,"Была активность"],["НОВЫЕ РЕГИСТРАЦИИ",data.newRegistrations,"Последние 24 часа"],["АКТИВНЫЕ КОМНАТЫ",data.activeRooms,"Открыты сейчас"],["СЫГРАНО ИГР",data.gamesPlayed,"Сохранено в базе"],["ВИРТУАЛЬНЫЕ МОНЕТЫ",adminMoney(data.virtualCoins),"Сумма балансов"]];$("adminStats").innerHTML=stats.map(x=>'<article class="admin-stat-card"><small>'+escapeHtml(x[0])+'</small><strong>'+escapeHtml(x[1])+'</strong><span>'+escapeHtml(x[2])+'</span></article>').join("");$("adminApiStatus").textContent="● BACKEND "+String(data.backend?.status||"unknown").toUpperCase();$("adminApiStatus").className="admin-status-pill "+(data.backend?.status==="online"?"online":"offline");$("adminSystemStatus").innerHTML='<div><span>Backend</span><b>'+escapeHtml(data.backend?.status||"unknown")+'</b></div><div><span>SQLite quick check</span><b>'+escapeHtml(data.backend?.database||"unknown")+'</b></div><div><span>Время работы</span><b>'+escapeHtml(Math.floor(Number(data.backend?.uptimeSeconds||0)/60))+' мин</b></div>';$("adminRecentEvents").innerHTML=data.recentEvents?.length?data.recentEvents.map(event=>'<div class="admin-event"><div><strong>'+escapeHtml(event.description||event.type)+'</strong><small>'+escapeHtml(event.type)+' · '+escapeHtml(event.player_id||"—")+'</small></div><small>'+escapeHtml(adminDate(event.created_at))+'</small></div>').join(""):'<div class="mp-list-empty">Событий пока нет.</div>'}
