async function submitAdminAction(action){if(!adminAllowed||!adminPlayerId)return;const reason=$("adminActionReason").value.trim(),amount=Number($("adminActionAmount").value);if(!reason)return toast("Для действия обязательна причина.");try{await apiRequest("/api/admin/players/"+encodeURIComponent(adminPlayerId)+"/action",{action,reason,amount,status:$("adminActionStatus").value});toast("Действие сохранено в журнале.");await Promise.all([loadAdminPlayer(adminPlayerId),loadAdminPlayers(adminPageNumber),loadAdminDashboard()])}catch(e){toast(e.message)}}
