function showBuildVersion(){const js=[...document.scripts].find(s=>s.src.includes("/app.js")),css=[...document.querySelectorAll('link[rel="stylesheet"]')].find(s=>s.href.includes("/style.css")),getVersion=el=>el?new URL(el.src||el.href,location.href).searchParams.get("v")||"local":"local",jsVersion=getVersion(js),cssVersion=getVersion(css),badge=$("appVersion");badge.textContent="ВЕРСИЯ JS "+jsVersion+" · CSS "+cssVersion;badge.title="Loaded app.js?v="+jsVersion+" and style.css?v="+cssVersion}
