async function loadRemoteSkinCatalog(){const note=$("marketPriceStatus");if(!API_BASE){note.textContent="Для актуального каталога и цен открой сайт через Render или запусти backend.";renderAll();return}try{const response=await fetch(API_BASE+"/api/skins",{cache:"no-store"});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||`Каталог скинов: ${response.status}`);const imported=(Array.isArray(data.skins)?data.skins:[]).filter(item=>item&&item.id&&item.name&&item.image&&Number.isFinite(Number(item.price))&&Number(item.price)>0&&String(item.image).startsWith("https://")).map(item=>({id:String(item.id),name:String(item.name),weapon:String(item.weapon||item.name.split("|")[0]||"Weapon").trim(),wear:String(item.wear||"Standard"),rarity:String(item.rarity||"Unknown"),price:Number(item.price),emoji:String(item.emoji||"🔫"),glow:/^#[0-9a-f]{3,8}$/i.test(String(item.glow||""))?String(item.glow):"#8297aa",image:String(item.image),marketHashName:String(item.marketHashName||item.name),marketUrl:String(item.marketUrl||""),priceSource:"Skinport"}));skins.splice(0,skins.length,...imported);state.inventory=state.inventory.filter(id=>getSkin(id));saveState();if(Array.isArray(data.cases)){const artwork=new Map(cases.map(item=>[item.id,item.image]));cases=data.cases.map(item=>({...item,image:artwork.get(item.id)||"",pool:Array.isArray(item.pool)?item.pool:[]}))}marketVisibleCount=48;upgradeTargetVisibleCount=60;const updated=data.priceUpdatedAt?new Date(data.priceUpdatedAt).toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"}):"ожидание";note.textContent=!data.priceUpdatedAt?"Источник цен временно недоступен; проверь backend и обнови страницу позже.":imported.length?`Skinport · минимальный активный лот · EUR · обновлено ${updated}. Баланс и кейсы используют виртуальные кредиты.`:"У Skinport сейчас нет активных лотов для найденных предметов.";console.info(`Market catalog loaded: ${skins.length} priced skins`);renderAll()}catch(error){note.textContent="Не удалось получить каталог и рыночные цены с сервера. Проверь API/Render.";console.warn("Skin catalog sync:",error.message);renderAll()}}
